@page "/book-appointment"
@rendermode InteractiveServer
@using sv_83d937d7e3a54893a4611c2361e942b4.Models
@using sv_83d937d7e3a54893a4611c2361e942b4.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

@* ── STEP 1: Patient Information ── *@
<h2>Step 1: Patient Information</h2>

<EditForm EditContext="step1Context" OnValidSubmit="HandleStep1Submit" FormName="step1">
    <DataAnnotationsValidator />

    <div>
        <label>
            Patient Name:
            <InputText @bind-Value="step1Model.PatientName" />
        </label>
        <ValidationMessage For="() => step1Model.PatientName" />
    </div>

    <div>
        <label>
            Email:
            <InputText @bind-Value="step1Model.Email" />
        </label>
        <ValidationMessage For="() => step1Model.Email" />
    </div>

    <div>
        <label>
            Phone:
            <InputText @bind-Value="step1Model.Phone" />
        </label>
        <ValidationMessage For="() => step1Model.Phone" />
    </div>

    <div>
        <label>
            Insurance Provider:
            <InputSelect @bind-Value="step1Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
        </label>
        <ValidationMessage For="() => step1Model.InsuranceProvider" />
    </div>

    <button type="submit">Next</button>
</EditForm>

@* ── STEP 2: Appointment Details ── *@
@if (showStep2)
{
    <h2>Step 2: Appointment Details</h2>

    <EditForm EditContext="step2Context" OnSubmit="HandleStep2Submit" FormName="step2">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        <div>
            <label>
                Preferred Doctor:
                <InputSelect @bind-Value="step2Model.Doctor" @bind:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
            </label>
            <ValidationMessage For="() => step2Model.Doctor" />
        </div>

        <div>
            <label>
                Date:
                <InputDate @bind-Value="step2Model.AppointmentDate" @bind:after="OnDateChanged" />
            </label>
            <ValidationMessage For="() => step2Model.AppointmentDate" />
        </div>

        <div>
            <label>
                Time Slot:
                <InputSelect @bind-Value="step2Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
            </label>
            <ValidationMessage For="() => step2Model.TimeSlot" />
        </div>

        <div>
            <label>
                Reason for Visit:
                <InputTextArea @bind-Value="step2Model.Reason" />
            </label>
            <ValidationMessage For="() => step2Model.Reason" />
        </div>

        <button type="submit" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
    </EditForm>
}

@if (isBooked)
{
    <div><strong>Appointment booked successfully!</strong></div>
}

@code {
    private Step1Model step1Model = new();
    private EditContext step1Context = default!;

    private Step2Model step2Model = new();
    private EditContext step2Context = default!;

    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isBooked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        step1Context = new EditContext(step1Model);
        step2Context = new EditContext(step2Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void HandleStep1Submit()
    {
        showStep2 = true;
    }

    private async Task OnDoctorChanged()
    {
        step2Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        step2Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(step2Model.Doctor) && step2Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                step2Model.Doctor, step2Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleStep2Submit()
    {
        customValidator?.ClearErrors();

        if (!step2Context.Validate())
        {
            return;
        }

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                step1Model.Email!,
                step1Model.InsuranceProvider!,
                step2Model.Doctor!,
                step2Model.TimeSlot!);

            if (errors.Count > 0)
            {
                // Map service field names to the correct model fields.
                // Email errors target step 1, so display them via the step 2 custom validator
                // by mapping to matching Step2Model field names where possible,
                // but Email is on Step1 — we need to handle this specially.
                var step2Errors = new Dictionary<string, List<string>>();

                foreach (var (field, messages) in errors)
                {
                    step2Errors[field] = messages;
                }

                customValidator!.DisplayErrors(step2Errors);
                return;
            }

            isBooked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

