<h2>Step 1: Patient Information</h2>

<EditForm EditContext="step1Context" OnValidSubmit="HandleStep1Submit" FormName="step1">
    <DataAnnotationsValidator />

    <div>
        <label>
            Patient Name:
            <InputText @bind-Value="step1Model.PatientName" />
        </label>
        <ValidationMessage For="() => step1Model.PatientName" />
    </div>

    <div>
        <label>
            Email:
            <InputText @bind-Value="step1Model.Email" />
        </label>
        <ValidationMessage For="() => step1Model.Email" />
    </div>

    <div>
        <label>
            Phone:
            <InputText @bind-Value="step1Model.Phone" />
        </label>
        <ValidationMessage For="() => step1Model.Phone" />
    </div>

    <div>
        <label>
            Insurance Provider:
            <InputSelect @bind-Value="step1Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
        </label>
        <ValidationMessage For="() => step1Model.InsuranceProvider" />
    </div>

    <button type="submit">Next</button>
</EditForm>

@* ── STEP 2: Appointment Details ── *@
@if (showStep2)
{
    <h2>Step 2: Appointment Details</h2>

    <EditForm EditContext="step2Context" OnSubmit="HandleStep2Submit" FormName="step2">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        <div>
            <label>
                Preferred Doctor:
                <InputSelect @bind-Value="step2Model.Doctor" @bind:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
            </label>
            <ValidationMessage For="() => step2Model.Doctor" />
        </div>

        <div>
            <label>
                Date:
                <InputDate @bind-Value="step2Model.AppointmentDate" @bind:after="OnDateChanged" />
            </label>
            <ValidationMessage For="() => step2Model.AppointmentDate" />
        </div>

        <div>
            <label>
                Time Slot:
                <InputSelect @bind-Value="step2Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
            </label>
            <ValidationMessage For="() => step2Model.TimeSlot" />
        </div>

