            <label>
                Reason for Visit:
                <InputTextArea @bind-Value="step2Model.Reason" />
            </label>
            <ValidationMessage For="() => step2Model.Reason" />
        </div>

        <button type="submit" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
    </EditForm>
}

@if (isBooked)
{
    <div><strong>Appointment booked successfully!</strong></div>
}

@code {
    private Step1Model step1Model = new();
    private EditContext step1Context = default!;

    private Step2Model step2Model = new();
    private EditContext step2Context = default!;

    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isBooked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        step1Context = new EditContext(step1Model);
        step2Context = new EditContext(step2Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void HandleStep1Submit()
    {
        showStep2 = true;
    }

    private async Task OnDoctorChanged()
    {
        step2Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        step2Model.TimeSlot = null;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(step2Model.Doctor) && step2Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                step2Model.Doctor, step2Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleStep2Submit()
    {
        customValidator?.ClearErrors();

        if (!step2Context.Validate())
        {
            return;
        }

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                step1Model.Email!,
                step1Model.InsuranceProvider!,
                step2Model.Doctor!,
                step2Model.TimeSlot!);

            if (errors.Count > 0)
            {
                // Map service field names to the correct model fields.
                // Email errors target step 1, so display them via the step 2 custom validator
                // by mapping to matching Step2Model field names where possible,
                // but Email is on Step1 — we need to handle this specially.
                var step2Errors = new Dictionary<string, List<string>>();

                foreach (var (field, messages) in errors)
                {
                    step2Errors[field] = messages;
                }

                customValidator!.DisplayErrors(step2Errors);
                return;
            }

            isBooked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
